function magnify(root){if(!root)return;root.querySelectorAll('svg').forEach(im=>{if(im.closest('.visual-scroll,[data-study-widget]'))return;const wrapper=document.createElement('div');wrapper.className='visual-scroll';wrapper.tabIndex=0;wrapper.setAttribute('aria-label','图示可横向滚动');im.before(wrapper);wrapper.append(im);const button=document.createElement('button');button.type='button';button.className='figure-zoom';button.textContent='放大图示 ↗';wrapper.after(button);button.onclick=()=>{let dialog=document.getElementById('figure-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='figure-dialog';dialog.setAttribute('aria-label','放大的图示');dialog.innerHTML='<button type="button" class="figure-close">关闭图示</button><div class="figure-stage"></div>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});}dialog.querySelector('.figure-stage').replaceChildren(im.cloneNode(true));dialog.showModal();};});}
function knowledgeBackground(lesson,scene){const k=g.S17MudKnowledge?.[scene];if(!k)return null;const cards=k.sections.map((b,i)=>`<article class="panel knowledge-chapter" data-knowledge-section="${i}"><div class="knowledge-chapter-no">${String(i+1).padStart(2,'0')} / ${b.en}</div><h2>${b.title}</h2>${b.html}</article>`).join('');const original=lesson.background.map(b=>`<article class="knowledge-old-figure"><h3>${b.title}</h3><figure>${b.svg??b.html}<figcaption>${b.caption}</figcaption></figure></article>`).join('');return cards+`<details class="panel knowledge-supplement"><summary>补充图解：展开原有场景示意与概念图</summary><p>读完前面的知识后，再用图回看采集过程和概念关系。</p>${original}</details>`;}
function explainStep(scene){const k=g.S17MudKnowledge?.[scene],target=document.getElementById('step-content');if(!k||!target)return;const index=Number(document.querySelector('#stepnav button.active')?.dataset.step??0),content=target.querySelector('article'),heading=content?.querySelector('h2');if(!heading||content.querySelector('[data-knowledge-step]'))return;const copy=document.createElement('div');copy.className='knowledge-step-copy';copy.dataset.knowledgeStep=index;copy.innerHTML='<h3>'+k.flow[index][0]+'</h3><p>'+k.flow[index][1]+'</p>';heading.textContent='步骤 '+(index+1)+' · '+heading.textContent.replace(/^图\s*S\d+\s*[｜|]\s*/,'');heading.after(copy);}
function init(scene,showTab){const lesson=g[scene.toUpperCase()+'Lesson'],reading=knowledgeBackground(lesson,scene);if(reading){document.getElementById('background-content').innerHTML=reading;explainStep(scene);new MutationObserver(()=>explainStep(scene)).observe(document.getElementById('step-content'),{childList:true,subtree:true});}const studyKnowledge=g.S17MudKnowledge?.[scene];if(studyKnowledge?.workflowOverview&&!document.querySelector('.study-workflow-overview'))document.getElementById('stepnav')?.insertAdjacentHTML('beforebegin',studyKnowledge.workflowOverview);const tour=tours[scene],nav=document.querySelector('nav[aria-label="案例内容"]');if(!nav)return;const guide=document.createElement('aside');guide.className='lesson-guide';guide.innerHTML=`<div><span class="guide-kicker">先看懂，再亲手验证</span><h2>${tour.title}</h2><p>${tour.try}</p></div><div class="guide-points"><p><b>看哪里</b>${tour.watch}</p><p><b>接着核对</b>${tour.limit}</p></div><div class="guide-actions"><button type="button" data-guide-run class="primary">${tour.button} →</button><button type="button" data-guide-method>先逐步看方法</button></div>`;nav.before(guide);guide.querySelector('[data-guide-run]').onclick=()=>{const preset=document.getElementById('preset');preset.value=tour.preset;preset.dispatchEvent(new Event('change',{bubbles:true}));showTab('lab');document.getElementById('run').click();document.getElementById('lab').scrollIntoView({block:'start',behavior:'smooth'});};guide.querySelector('[data-guide-method]').onclick=()=>showTab('workflow');const syncGuide=()=>{guide.hidden=!document.getElementById('background').hidden||!document.getElementById('workflow').hidden;};new MutationObserver(syncGuide).observe(document.getElementById('background'),{attributes:true,attributeFilter:['hidden']});new MutationObserver(syncGuide).observe(document.getElementById('workflow'),{attributes:true,attributeFilter:['hidden']});magnify(document.getElementById('background-content'));g.S17Study?.mount(document.getElementById('background-content'));g.S17Flow?.mount(document.getElementById('workflow'));showTab(['background','workflow','lab'].includes(location.hash.slice(1))?location.hash.slice(1):'background');syncGuide();
 if(scene==='m2'){const transport=document.getElementById('transport')?.closest('article');if(transport){const more=document.createElement('details');more.className='panel knowledge-supplement';more.innerHTML='<summary>补充实验：播放简化循环迟到示意</summary>';transport.before(more);more.append(transport);}}
 if(scene==='m3'&&g.S17Images){const box=document.createElement('article');box.className='panel pair-preview';box.innerHTML='<h2>先观察：同一教学样品的实际白光 / UV 像素</h2><p>同一教学样品 DEMO-017-P1 的白光与UV，位置一致；调整曝光观察亮度与饱和变化。</p><label>观察曝光 <input id="preview-exposure" type="range" min="0.4" max="5" step="0.1" value="1"></label><div class="pair-images"><figure><canvas id="preview-white" aria-label="背景观察白光像素"></canvas><figcaption>白光：轮廓与纹理</figcaption></figure><figure><canvas id="preview-uv" aria-label="背景观察UV像素"></canvas><figcaption>UV：同位置的发光观察</figcaption></figure></div><p id="preview-quality"></p><button id="preview-to-lab">用当前曝光进行分割 →</button>';const more=document.createElement('details');more.className='panel knowledge-supplement';more.innerHTML='<summary>补充观察：调节实际教学像素的白光与UV曝光</summary>';document.getElementById('background-content').append(more);more.append(box);const draw=()=>{const exposure=Number(document.getElementById('preview-exposure').value),o=g.S17Images.sample(17,{exposure},1).observations;for(const [id,im]of [['preview-white',o.white],['preview-uv',o.uv]]){const c=document.getElementById(id);c.width=im.width;c.height=im.height;c.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(im.pixels),im.width,im.height),0,0);}let n=0;for(let i=0;i<o.uv.pixels.length;i+=4)if(o.uv.pixels[i]>=255||o.uv.pixels[i+1]>=255||o.uv.pixels[i+2]>=255)n++;document.getElementById('preview-quality').textContent='曝光 '+exposure.toFixed(1)+'；实际饱和像素 '+n+'/'+(o.uv.width*o.uv.height)+'（任一RGB通道达255，分母为整幅图像）。';};document.getElementById('preview-exposure').oninput=draw;document.getElementById('preview-to-lab').onclick=()=>{document.getElementById('preset').value='default';document.getElementById('preset').dispatchEvent(new Event('change',{bubbles:true}));document.getElementById('sample').value='1';document.getElementById('exposure').value=document.getElementById('preview-exposure').value;document.getElementById('exposure').dispatchEvent(new Event('input',{bubbles:true}));showTab('lab');document.getElementById('run').click();};draw();}
}
function bars(items,title,{signed=false}={}){const max=Math.max(1e-12,...items.map(v=>Math.abs(v.value)));return `<div class="value-chart" role="group" aria-label="${esc(title)}"><h4>${esc(title)}</h4>${items.map(v=>{const width=Math.abs(v.value)/max*(signed?50:100),left=signed?(v.value<0?50-width:50):0;return `<div class="value-row"><span>${esc(v.name)}</span><div class="value-track ${signed?'signed':''}"><i style="left:${left}%;width:${width}%;background:${v.value<0?'#ad7546':'#367d61'}"></i></div><output>${Number(v.value).toFixed(3)}</output></div>`;}).join('')}</div>`;}
function evidenceGraph(claim,fact,source){const fieldNames={depthRangeMD_m:'深度 / m MD',timeRange_s:'时间 / s',negation:'否定标记',uncertainty:'不确定标记',rock:'岩性关键词',gasValue:'气体数值',gasUnit:'气体单位'};const fields=fact?Object.entries(fact.fields).filter(([,v])=>v!=null).map(([k,v])=>`<span><b>${esc(fieldNames[k]??k)}</b> ${esc(typeof v==='boolean'?(v?'是':'否'):typeof v==='object'?JSON.stringify(v):v)}</span>`).join(''):'<span>上游观察 / 模型候选：按原包保留</span>';return `<div class="evidence-graph" aria-label="当前句子到事实与来源的关系"><div><small>当前句子 · 修订 ${claim.revision}</small><p>${esc(claim.statement)}</p><b>${esc(claim.reviewStatus)}</b></div><span class="evidence-arrow" aria-hidden="true">→</span><div><small>${fact?'来源自动抽取字段':'上游证据'}</small>${fields}</div><span class="evidence-arrow" aria-hidden="true">→</span><div><small>具体来源 · v${source.sourceVersion}</small><b>${esc(source.sourceRecordId)}</b><p>${esc(JSON.stringify(claim.sourceRefs[0].selector))}</p><span>能定位 ≠ 已核对含义</span></div></div>`;}
g.S17TeachingView={apply,init,magnify,bars,evidenceGraph,knowledgeBackground};
