function state(ready){const p=document.getElementById('visual-explorer');if(!p)return;p.dataset.ready=String(ready===true||ready==='ready');const yes=p.dataset.ready==='true';p.classList.toggle('vx-stale',!yes);p.querySelector('.vx-readiness').textContent=yes?'本次运行已更新 · 可交互探索':'旧结果 / 正在计算：重算完成后再探索';p.querySelector('.vx-body').inert=!yes;}
